using namespace std;

signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	string s,t;
	cin>>s>>t;
	for(int i=0;i<s.size();i++){
		if((s[i]==t[0]||s[i]=='?')&&i+t.size()<=s.size()){
			bool f=1;

			for(int j=0;j<t.size();j++){
//				cout<<(j+i)<<endl;
				if(s[j+i]!=t[j]&&s[j+i]!='?'){
					f=0;
					break;
				}
			}
//			cout<<"^_^";
			if(f){
				for(int j=0;j<t.size();j++){
					s[j+i]=t[j];
				}
				for(int j=0;j<s.size();j++){
					if(s[j]=='?'){
						s[j]='a';
					}
				}
				cout<<s;
				return 0;
			}
		}
	}
	cout<<"UNRESTORABLE";
	return 0;
}
